import csv
import io
import itertools
import unittest

from ledger import api, csv_bank_import


class BankCsvTests(unittest.TestCase):
    parsers = (csv_bank_import.parse_bank_csv, api.parse_bank_csv)

    def test_header_orders_and_preserved_fields(self):
        fields = {\"reference\": ' ref,\"quoted\"\\r\\nnext ',
                  \"amount\": \"+0012\", \"memo\": ' memo,one\\n\"two\" '}
        for headers in itertools.permutations(fields):
            stream = io.StringIO(newline=\"\")
            writer = csv.writer(stream, lineterminator=\"\\r\\n\")
            writer.writerow(headers)
            writer.writerow([fields[key] for key in headers])
            for bom in (\"\", \"\\ufeff\"):
                for parser in self.parsers:
                    with self.subTest(headers=headers, bom=bom, parser=parser):
                        self.assertEqual(parser(bom + stream.getvalue()), [{
                            \"reference\": fields[\"reference\"], \"amount\": 12,
                            \"memo\": fields[\"memo\"],
                        }])

    def test_integer_amounts_and_empty_strings(self):
        for parser in self.parsers:
            self.assertEqual(parser(\"reference,amount,memo\\n,-12,\\na,0,b\\nc,-0,d\"), [
                {\"reference\": \"\", \"amount\": -12, \"memo\": \"\"},
                {\"reference\": \"a\", \"amount\": 0, \"memo\": \"b\"},
                {\"reference\": \"c\", \"amount\": 0, \"memo\": \"d\"},
            ])
            self.assertEqual(parser(\"\\ufeffmemo,reference,amount\\r\\n\"), [])

    def test_invalid_inputs_raise_in_both_entry_points(self):
        invalid = [
            \"\", \"\\ufeff\", \"\\n\", \"reference,amount\\n\",
            \"reference,amount,memo,other\\n\", \"reference,amount,amount\\n\",
            \"Reference,amount,memo\\n\", \"reference,amount,memo\\na,1\\n\",
            \"reference,amount,memo\\na,1,b,c\\n\",
            \"reference,amount,memo\\n\\n\",
            'reference,amount,memo\\na,1,\"unclosed',
            'reference,amount,memo\\na,1,\"closed\"junk\\n',
            '\"reference,amount,memo',
            \"reference,amount,memo\\na,1,ok\\nb,no,bad\\n\",
        ]
        invalid.extend(\"reference,amount,memo\\na,\" + amount + \",b\\n\"
                       for amount in (\"\", \"+\", \"-\", \"1.0\", \"1e2\", \" 1\", \"1 \",
                                      \"1_000\", \"１２\", \"١\", \"--1\"))
        for parser in self.parsers:
            for text in invalid:
                with self.subTest(parser=parser, text=text):
                    with self.assertRaises(ValueError):
                        parser(text)
EOF
